    throw new Error("Active path escaped its output namespace.");
  }

  async function lstatOrNull(value) {
    try { return await fs.lstat(value); }
    catch (error) { if (error.code === "ENOENT") return null; throw error; }
  }
  function requireDirectory(value, stat) {
    if (!stat || stat.isSymbolicLink() || !stat.isDirectory()) throw new Error(`Unsafe output ancestor: ${value}`);
