    let stat = await lstatOrNull(value);
    if (!stat) {
      try { await fs.mkdir(value); }
      catch (error) { if (error.code !== "EEXIST") throw error; }
      stat = await fs.lstat(value);
    }
    requireDirectory(value, stat);
    identities.set(value, { dev: stat.dev, ino: stat.ino });
